package bzh.enssat.unolingo.sound

import android.content.Context
import android.media.AudioAttributes
import android.media.SoundPool
import bzh.enssat.unolingo.R

/** Short feedback sound played when an answer is checked. */
fun interface AnswerSoundPlayer {
    fun play(correct: Boolean)
}

/**
 * Plays `res/raw/answer_correct` and `answer_wrong` (original sounds generated by `tools/gen_sounds.py`).
 * App-wide singleton: the sounds are loaded once and kept for the app's lifetime.
 */
class SoundPoolAnswerPlayer(context: Context) : AnswerSoundPlayer {
    private val soundPool = SoundPool.Builder()
        .setMaxStreams(2)
        .setAudioAttributes(
            AudioAttributes.Builder()
                .setUsage(AudioAttributes.USAGE_GAME)
                .setContentType(AudioAttributes.CONTENT_TYPE_SONIFICATION)
                .build(),
        )
        .build()

    // Loading is asynchronous; a sound requested before it is ready is simply skipped.
    private val correctSound = soundPool.load(context.applicationContext, R.raw.answer_correct, 1)
    private val wrongSound = soundPool.load(context.applicationContext, R.raw.answer_wrong, 1)

    override fun play(correct: Boolean) {
        soundPool.play(if (correct) correctSound else wrongSound, 1f, 1f, 1, 0, 1f)
    }
}
